{"policy":"permit (
    principal is User,
    action == Action::"draftLease",
    resource is Lease
)
when {
    principal.holdsLeasingAgentRole
};

permit (
    principal is User,
    action == Action::"viewAuditLog",
    resource is AuditLog
)
when {
    principal.holdsAuditorRole
};

permit (
    principal is User,
    action == Action::"reviewLease",
    resource is Lease
)
when {
    principal.holdsBrokerRole
};

forbid (
    principal is User,
    action == Action::"reviewLease",
    resource is Lease
)
when {
    !principal.holdsBrokerRole
};

forbid (
    principal is User,
    action == Action::"reviewLease",
    resource is Lease
)
when {
    resource.isHighValue &&
    principal == resource.listingAgent &&
    resource.squareFootage <= context.largePremisesThreshold &&
    !context.courtOrderDeclared
};"}
